  public get fullRemoteServerUrl() {
    if (!this.remoteServerUrl) {
      return undefined;
    }

    let url = this.remoteServerUrl.toLowerCase();

    if (!url.startsWith("http") && url.indexOf("//") < 0) {
      if (url.indexOf("localhost") >= 0) {
        url = "http://" + url;
      } else {
        url = "https://" + url;
      }
    }

    url = Utilities.ensureEndsWithSlash(url);

    return url;
  }

